        public static UnitConverterMassConcentrationUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterMassConcentrationUnit>();
            for (int i = 0; i < 50; i++) if (GetUnitSystem((UnitConverterMassConcentrationUnit)i) == system) units.Add((UnitConverterMassConcentrationUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterMassConcentrationUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterMassConcentrationUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterMassConcentrationUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterMassConcentrationUnit)id : default(UnitConverterMassConcentrationUnit); return success;
        }

        public static UnitConverterMassConcentrationUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterMassConcentrationUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous MassConcentration unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterMassConcentrationValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterMassConcentrationValue(value, (UnitConverterMassConcentrationUnit)id) : default(UnitConverterMassConcentrationValue); return success;
        }

        public static UnitConverterMassConcentrationValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterMassConcentrationValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous MassConcentration unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterMassConcentrationUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


